#!/usr/bin/env python3
"""
Neural Network Generative Art - Interactive visualization of firing neurons
"""

import pygame
import math
import random
import sys

BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
NEURAL_BLUE = (0, 150, 255)
PULSE_YELLOW = (255, 255, 100)
SYNAPSE_PINK = (255, 100, 200)
NEURAL_GREEN = (100, 255, 150)
GRAY = (100, 100, 100)

class Neuron:
    def __init__(self, x, y, size=5):
        self.x, self.y = x, y
        self.size, self.base_size = size, size
        self.pulse, self.pulse_speed = 0, 0
        self.max_pulse, self.fire_time = 1, 0
        self.is_firing = False

    def update(self, time, pulse_speed):
        if self.is_firing:
            self.pulse_speed = pulse_speed
            self.pulse = min(self.pulse + self.pulse_speed, self.max_pulse)
            if self.pulse >= self.max_pulse:
                self.is_firing = False
        else:
            self.pulse = max(self.pulse - self.pulse_speed, 0)

    def draw(self, screen, time):
        pulse_radius = self.size + self.pulse * 2
        pygame.draw.circle(screen, NEURAL_BLUE, (int(self.x), int(self.y)), self.size)
        if self.pulse > 0.3:
            alpha = int(self.pulse * 255)
            pygame.draw.circle(screen, (0, alpha, 255), (int(self.x), int(self.y)), 
                             self.size + self.pulse * 10, 2)
        if self.is_firing:
            cx, cy = int(self.x), int(self.y)
            for i in range(4):
                angle = (i * math.pi / 2) + time * 0.5
                px, py = cx + math.cos(angle) * (self.size + self.pulse * 20), \
                         cy + math.sin(angle) * (self.size + self.pulse * 20)
                pygame.draw.circle(screen, PULSE_YELLOW, (int(px), int(py)), 3)

class NeuralNetwork:
    def __init__(self, width, height, density=0.5, pulse_speed=0.5, connection_range=150):
        self.width, self.height = width, height
        self.density_param, self.pulse_speed_param = density, pulse_speed
        self.connection_range_param = connection_range
        self.neurons, self.connections = [], []
        self.time = 0
        self.center_x, self.center_y = width // 2, height // 2

        self._create_neurons()
        self._create_connections()

    def _create_neurons(self):
        for _ in range(int(20 * self.density_param)):
            x = random.gauss(self.center_x, self.width * 0.2)
            y = random.gauss(self.center_y, self.height * 0.2)
            self.neurons.append(Neuron(x, y, size=random.randint(3, 8)))
        for _ in range(int(15 * self.density_param)):
            angle = random.uniform(0, 2 * math.pi)
            dist = random.randint(self.width * 0.3, self.width * 0.8)
            x, y = self.center_x + math.cos(angle) * dist, \
                   self.center_y + math.sin(angle) * dist
            self.neurons.append(Neuron(x, y, size=random.randint(2, 5)))
        for _ in range(int(10 * self.density_param)):
            self.neurons.append(Neuron(random.uniform(0, self.width), 
                                       random.uniform(0, self.height),
                                       size=random.randint(2, 4)))

    def _create_connections(self):
        self.connections = []
        for i, n1 in enumerate(self.neurons):
            for n2 in self.neurons[i+1:]:
                dist = math.hypot(n1.x - n2.x, n1.y - n2.y)
                if dist < self.connection_range_param:
                    strength = max(0, 1 - dist / self.connection_range_param)
                    if random.random() < 0.3 + self.density_param * 0.2:
                        self.connections.append({
                            'neuron1': n1, 'neuron2': n2,
                            'strength': strength,
                            'type': random.choice(['synapse', 'axon', 'dendrite'])
                        })

    def update(self):
        self.time += 0.016
        if random.random() < self.density_param * 0.05:
            random.choice(self.neurons).is_firing = True
        for n in self.neurons:
            n.update(self.time, self.pulse_speed_param)

    def draw(self, screen):
        for conn in self.connections:
            n1, n2, strength = conn['neuron1'], conn['neuron2'], conn['strength']
            if conn['type'] == 'synapse':
                color = (int(255 * strength), int(150 * strength), int(200 * strength))
            elif conn['type'] == 'axon':
                color = (int(100 * strength), int(255 * strength), int(150 * strength))
            else:
                color = (int(50 * strength), int(180 * strength), int(255 * strength))
            width = 1 + strength * 4
            pygame.draw.line(screen, color, (int(n1.x), int(n1.y)), (int(n2.x), int(n2.y)), width)
            if n1.is_firing or n2.is_firing:
                pulse_alpha = int((n1.pulse + n2.pulse) * 255)
                if pulse_alpha > 0:
                    pygame.draw.line(screen, (255, pulse_alpha, 100),
                                    (int(n1.x), int(n1.y)), (int(n2.x), int(n2.y)), max(2, width + 1))
        for n in self.neurons:
            n.draw(screen, self.time)

    def draw_ui(self, screen, font):
        screen.fill(BLACK)
        lines = ["NEURAL NETWORK VISUALIZER", "========================", "",
                 f"Density: {self.density_param:.2f}", f"Pulse Speed: {self.pulse_speed_param:.2f}",
                 f"Connection Range: {self.connection_range_param}", f"Neurons: {len(self.neurons)}",
                 f"Connections: {len(self.connections)}", "", "Controls:",
                 "Arrow Up/Down: Density | Right/Left: Pulse Speed",
                 "Page Up/Down: Connection Range | Click: Stimulate",
                 "R: Regenerate | ESC: Quit"]
        y = 10
        for line in lines:
            color = WHITE if line == "========================" else GRAY
            screen.blit(font.render(line, True, color), (10, y))
            y += 16

